    Bug 1903743 - Avoid trying to register calendars that were already registered. r=freaktechnik

    Differential Revision: https://phabricator.services.mozilla.com/D253804

diff --git a/calendar/base/content/dialogs/calendar-creation.js b/calendar/base/content/dialogs/calendar-creation.js
index dd4e2d88d95..c9771eea3e9 100644
--- a/calendar/base/content/dialogs/calendar-creation.js
+++ b/calendar/base/content/dialogs/calendar-creation.js
@@ -807,8 +807,13 @@ function prepareNetworkCalendar(calendar) {
  * close.
  */
 function createNetworkCalendars() {
+  const registeredCalendars = cal.manager.getCalendars();
   for (const listItem of document.getElementById("network-calendar-list").children) {
     if (listItem.querySelector(".calendar-selected").checked) {
+      if (registeredCalendars.some(c => c.id == listItem.calendar.id)) {
+        // Already registered.
+        continue;
+      }
       cal.manager.registerCalendar(listItem.calendar);
     }
   }
